//! The configuration's JSON Schema, as written in `proksi.hcl` or `proksi.yaml`: editors use it
//! for completion and docs (`docs/schema/proksi.schema.json`, kept up to date by CI).

#[cfg(test)]
use serde_json::Value;

/// Where the schema is kept, and published from (by its GitHub URL)
#[cfg(test)]
const FILE: &str = "docs/schema/proksi.schema.json";

/// The schema, with the docs of every setting. Generated by the tests only (`make schema`): the
/// release binary doesn't carry it.
#[cfg(test)]
pub fn schema() -> Value {
    let mut schema = schemars::schema_for!(super::Config).to_value();
    schema["title"] = "Proksi configuration".into();
    schema["$id"] =
        format!("https://raw.githubusercontent.com/luizfonseca/proksi/main/{FILE}").into();
    let mut defs = schema
        .as_object_mut()
        .and_then(|schema| schema.remove("$defs"))
        .unwrap_or_default();
    optional(&mut schema, &mut defs);
    schema["$defs"] = defs;
    schema
}

#[cfg(test)]
/// Files are merged with Proksi's defaults: the top level, and the blocks always there with it
/// (`store`, `server`...), have nothing required. Optional blocks, items of lists and maps, and
/// blocks' settings keep what they require: nothing fills them in.
fn optional(schema: &mut Value, defs: &mut Value) {
    if let Some(schema) = schema.as_object_mut() {
        schema.remove("required");
    }
    let refs: Vec<String> = schema["properties"]
        .as_object()
        .into_iter()
        .flat_map(|properties| properties.values())
        .filter_map(|property| property["$ref"].as_str())
        .filter_map(|reference| reference.strip_prefix("#/$defs/"))
        .map(str::to_string)
        .collect();
    for name in refs {
        let mut def = defs[&name].take();
        optional(&mut def, defs);
        defs[&name] = def;
    }
}

/// A value from `values`, in lower or upper case, as Proksi reads them
fn any_case(description: &str, values: &[&str]) -> schemars::Schema {
    let values: Vec<String> = values
        .iter()
        .flat_map(|value| [value.to_string(), value.to_uppercase()])
        .collect();
    schemars::json_schema!({ "type": "string", "description": description, "enum": values })
}

pub fn store_type(_: &mut schemars::SchemaGenerator) -> schemars::Schema {
    any_case(
        "Where certificates, routes and shared state are kept",
        &["memory", "redis", "sqlite", "postgres"],
    )
}

pub fn docker_mode(_: &mut schemars::SchemaGenerator) -> schemars::Schema {
    any_case(
        "Docker containers, or Docker Swarm services",
        &["container", "swarm"],
    )
}

pub fn proto_version(_: &mut schemars::SchemaGenerator) -> schemars::Schema {
    any_case("A TLS version", &["v1.1", "v1.2", "v1.3"])
}

pub fn cache_type(_: &mut schemars::SchemaGenerator) -> schemars::Schema {
    any_case("Where cached responses are kept", &["memcache", "disk"])
}

pub fn log_level(_: &mut schemars::SchemaGenerator) -> schemars::Schema {
    any_case(
        "The least important logs written",
        &["trace", "debug", "info", "warn", "error"],
    )
}

pub fn log_format(_: &mut schemars::SchemaGenerator) -> schemars::Schema {
    any_case("How logs are written", &["json", "pretty"])
}

pub fn log_rotation(_: &mut schemars::SchemaGenerator) -> schemars::Schema {
    any_case(
        "When log files start over",
        &["never", "daily", "hourly", "minutely"],
    )
}

#[cfg(test)]
mod tests {
    use std::path::Path;

    use clap::Parser;
    use serde_json::Value;

    use figment::providers::Format;

    use crate::config::{hcl::HclFormat, load_from_path, Config};

    fn validator() -> jsonschema::Validator {
        jsonschema::validator_for(&super::schema()).unwrap()
    }

    /// `text` as data, as Proksi reads it (HCL with its functions evaluated)
    fn hcl(text: &str) -> Option<Value> {
        HclFormat::from_str::<Value>(text).ok()
    }

    /// Whether Proksi loads `text` as its whole configuration
    fn accepted(text: &str) -> bool {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("proksi.hcl");
        std::fs::write(&path, text).unwrap();
        load_from_path(
            path.to_str().unwrap(),
            &Config::parse_from(["proksi"]),
            false,
        )
        .is_ok()
    }

    fn errors(value: &Value) -> Vec<String> {
        validator()
            .iter_errors(value)
            .map(|err| format!("{}: {err}", err.instance_path))
            .collect()
    }

    /// `docs/schema/proksi.schema.json` is the schema of this code. `make schema` writes it
    /// (`PROKSI_WRITE_SCHEMA`); the schema workflow checks it (`PROKSI_CHECK_SCHEMA`).
    #[test]
    fn test_the_published_schema_is_up_to_date() {
        let path = Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../..")
            .join(super::FILE);
        let schema = serde_json::to_string_pretty(&super::schema()).unwrap() + "\n";
        if std::env::var_os("PROKSI_WRITE_SCHEMA").is_some() {
            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
            std::fs::write(&path, &schema).unwrap();
        }
        if std::env::var_os("PROKSI_CHECK_SCHEMA").is_none() {
            return;
        }
        let published = std::fs::read_to_string(&path).unwrap_or_default();
        assert!(
            published == schema,
            "the configuration's schema changed: run `make schema` and commit {}",
            super::FILE
        );
    }

    #[test]
    fn test_the_examples_follow_the_schema() {
        let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../examples");
        let hcl_example = hcl(&std::fs::read_to_string(root.join("example.hcl")).unwrap()).unwrap();
        assert_eq!(errors(&hcl_example), Vec::<String>::new(), "example.hcl");
        let yaml: Value =
            figment::Figment::from(figment::providers::Yaml::file(root.join("example.yaml")))
                .extract()
                .unwrap();
        assert_eq!(errors(&yaml), Vec::<String>::new(), "example.yaml");
    }

    /// Every HCL configuration in the docs that Proksi accepts follows the schema
    #[test]
    fn test_the_docs_configurations_follow_the_schema() {
        let docs = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../docs");
        let mut checked = 0;
        for page in pages(&docs) {
            let text = std::fs::read_to_string(&page).unwrap();
            for snippet in hcl_snippets(&text) {
                let Some(value) = hcl(&snippet).filter(|_| accepted(&snippet)) else {
                    continue;
                };
                checked += 1;
                let errors = errors(&value);
                assert!(
                    errors.is_empty(),
                    "{}:\n{snippet}\n{errors:#?}",
                    page.display()
                );
            }
        }
        // Most snippets are whole configurations
        assert!(checked > 50, "only {checked} snippets checked");
    }

    #[test]
    fn test_unknown_settings_are_flagged() {
        let value = hcl("host \"a.test\" {\n  locaton \"/\" {}\n}\n").unwrap();
        assert!(!errors(&value).is_empty());
        let value = hcl("host \"a.test\" {\n  location \"/\" {\n    rate_limit {\n      requests = 1\n      per = \"1m\"\n      burts = 2\n    }\n  }\n}\n").unwrap();
        assert!(!errors(&value).is_empty());
    }

    #[test]
    fn test_settings_have_docs() {
        let schema = super::schema().to_string();
        assert!(schema.contains("Requests a client may make at once on top of `requests`"));
    }

    fn pages(dir: &Path) -> Vec<std::path::PathBuf> {
        let mut found = vec![];
        for entry in std::fs::read_dir(dir).unwrap().flatten() {
            let path = entry.path();
            if path.is_dir() {
                found.extend(pages(&path));
            } else if path.extension().is_some_and(|ext| ext == "mdx") {
                found.push(path);
            }
        }
        found
    }

    fn hcl_snippets(text: &str) -> Vec<String> {
        text.split("```hcl")
            .skip(1)
            .filter_map(|rest| rest.split("```").next())
            .map(str::to_string)
            .collect()
    }
}
